def compute(vars):
    total = vars["v2"]
    if total == 0:
        return None

    value = vars["v1"] / total * 100
    return {
        "value": value,
        "trace": {
            "non_us_dollar_denominated": vars["v1"],
            "total_average": total,
            "ratio": vars["v1"] / total,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
